import { Agent, run, tool } from "@openai/agents";
import { z } from "zod";

if (typeof run !== "function") {
  throw new Error("Expected run export");
}
const pingTool = tool({
  name: "ping",
  description: "Return pong",
  parameters: z.object({}),
  execute: async () => "pong",
});
const agent = new Agent({
  name: "DocrunAssistant",
  instructions: "You are a helpful assistant.",
  tools: [pingTool],
});
if (agent.name !== "DocrunAssistant" || agent.tools.length !== 1) {
  throw new Error("Expected Agent with registered tool");
}
console.log("openai-agents-ready");
